    /**
     * Create a new component instance.
     */
    public function __construct(
        public string $name,
        public ?string $label = null,
        public int $size = 20,
        public string $strokeWidth = '1.75',
    ) {}

    /**
     * Determine whether the icon set contains the given name.
     */
    public static function has(string $name): bool
    {
        return array_key_exists($name, self::ICONS);
    }

    /**
     * Get every icon name in the set, alphabetically.
     *
     * @return list<string>
     */
    public static function names(): array
    {
        return array_keys(self::ICONS);
    }

    /**
     * Determine whether the requested name falls back to the neutral placeholder.
     */
    public function isFallback(): bool
    {
        return ! self::has($this->name);
    }

    /**
     * Get the inner SVG markup for the requested icon, or the placeholder for unknown names.
     */
    public function markup(): string
    {
        return self::ICONS[$this->name] ?? self::ICONS[self::FALLBACK];
    }

    /**
     * Get the view / contents that represent the component.
     */
    public function render(): View|Closure|string
    {
        return view('components.icon');
    }
}
